import json
from pathlib import Path
import pandas as pd
from .config import ROOT,FEATURE_SETS
from .preflight import sha
from .model_selection import LIMITATIONS

OUT=ROOT/'reports/modeling'

def table(frame):
    f=frame.copy()
    for c in f.select_dtypes('number'):f[c]=f[c].map(lambda v:f'{v:.5f}' if pd.notna(v) else 'not applicable')
    return '| '+' | '.join(f.columns)+' |\n| '+' | '.join(['---']*len(f.columns))+' |\n'+'\n'.join('| '+' | '.join(str(v).replace('|','/').replace('\n',' ') for v in row)+' |' for row in f.itertuples(index=False,name=None))+'\n'

def generate():
    metadata=json.loads((ROOT/'models/model_metadata.json').read_text());hardware=json.loads((OUT/'hardware_environment.json').read_text());records=json.loads((OUT/'experiment_records.json').read_text());design=json.loads((OUT/'training_design.json').read_text());decisions=json.loads((OUT/'selection_decisions.json').read_text())
    comparison=pd.read_csv(OUT/'model_comparison.csv');best=comparison[comparison.feature_set.isin(FEATURE_SETS)].sort_values('PR_AUC',ascending=False).drop_duplicates('feature_set')
    calibration=pd.read_csv(OUT/'calibration_comparison.csv');sensitivity=pd.read_csv(OUT/'missingness_sensitivity.csv');subgroups=pd.read_csv(OUT/'subgroup_metrics.csv');bench=pd.read_csv(OUT/'gpu_cpu_benchmark.csv');importance=pd.read_csv(OUT/'feature_importance.csv')
    metrics=pd.DataFrame([dict(dataset='validation',**metadata['validation_metrics']),dict(dataset='independent test',**metadata['test_metrics'])])
    metric_columns=['dataset','rows','positive_count','accuracy','balanced_accuracy','precision','recall','specificity','f1','roc_auc','pr_auc','brier','log_loss','TP','TN','FP','FN']
    successful=[r for r in records if r.get('status')=='success'];failed=[r for r in records if r.get('status')=='failed']
    tuning={p.stem:json.loads(p.read_text()) for p in OUT.glob('tuning_*.json')}
    total=sum(r.get('runtime_seconds',0) for r in records)+sum(t.get('runtime_seconds',0) for t in tuning.values())
    matched=comparison[(comparison.model==next(r['model_name'] for r in successful if r['experiment_id']==metadata['selected_experiment'])) & (comparison.calibration=='none') & (comparison.device==metadata['device_used']) & comparison.feature_set.isin(FEATURE_SETS) & ~comparison.experiment_id.str.startswith('benchmark__')].drop_duplicates('feature_set')
    if len(matched)<4:
        family_best=comparison[(comparison.model_family==metadata['model_family'])&(comparison.calibration=='none')&comparison.feature_set.isin(FEATURE_SETS)]
        matched=family_best.sort_values('PR_AUC',ascending=False).drop_duplicates('feature_set')
    effects={}
    if len(matched[matched.feature_set=='full_features']):
        full=matched[matched.feature_set=='full_features'].iloc[0]
        for feature_set in FEATURE_SETS:
            row=matched[matched.feature_set==feature_set]
            if len(row):effects[feature_set]=dict(PR_AUC_difference_vs_full=float(row.iloc[0].PR_AUC-full.PR_AUC),ROC_AUC_difference_vs_full=float(row.iloc[0].ROC_AUC-full.ROC_AUC))
    bench_rows=[]
    for model,rows in bench.groupby('model'):
        cpu=rows[rows.device=='CPU'];gpu=rows[rows.device=='GPU']
        bench_rows.append(dict(model=model,CPU_model_fit_seconds=float(cpu.iloc[0].model_fit_seconds) if len(cpu) else None,GPU_model_fit_seconds=float(gpu.iloc[0].model_fit_seconds) if len(gpu) else None,model_fit_speedup=float(cpu.iloc[0].model_fit_seconds/gpu.iloc[0].model_fit_seconds) if len(cpu) and len(gpu) else None,CPU_total_seconds=float(cpu.iloc[0].training_time) if len(cpu) else None,GPU_total_seconds=float(gpu.iloc[0].training_time) if len(gpu) else None))
    pd.DataFrame(bench_rows).to_csv(OUT/'gpu_cpu_benchmark_summary.csv',index=False)
    write=lambda name,text:(OUT/name).write_text(text,encoding='utf-8')
    failure_text='No recorded fit failures.' if not failed else '\n\n'.join(f'- {r["experiment_id"]}: {r.get("error")}' for r in failed)
    interruptions='CPU screening was checkpoint-resumed after launcher inspection and after the GPU-first request arrived. A training-only search was restarted to correct the native-category flag before tuned refits. Completed experiment rows were preserved; incomplete attempts have no fabricated metrics. Events are recorded in interrupted_runs.json.'
    sources='\n\nImplementation references: [sklearn calibration and disjoint fit/calibration](https://scikit-learn.org/stable/modules/generated/sklearn.calibration.CalibratedClassifierCV.html), [XGBoost GPU configuration](https://xgboost.readthedocs.io/en/stable/gpu/), [CatBoost Tree SHAP](https://catboost.ai/docs/en/concepts/python-reference_catboostclassifier_get_feature_importance), [LightGBM Windows GPU builds](https://lightgbm.readthedocs.io/en/stable/Installation-Guide.html).\n'
    training=f'# Training report\n\nPurpose: classify profiles associated with EXISTING reported CHD/MI in CDC BRFSS 2021. No future-risk endpoint or clinical diagnosis is modeled.\n\nVerified dimensions: cleaned 434,058 x 17; train 303,841 x 17; validation 65,109 x 17; test 65,108 x 17. Class counts match the required fixed split. Test features were used initially only for requested schema/count/membership integrity checks; test predictions were made once after freeze. No datasets or CDC mappings changed.\n\nHardware: {hardware["CPU_model"]}; {hardware["logical_CPU_count"]} logical CPUs; RAM {hardware.get("RAM_total_bytes",0)/2**30:.2f} GiB; GPU {hardware["GPU_model"]}, {hardware["VRAM_total_MiB"]} MiB; driver {hardware["NVIDIA_driver"]}. Driver CUDA compatibility {hardware["driver_CUDA_compatibility_version"]}; this is not an independently detected runtime. XGBoost compiled CUDA details and toolkit detection are in hardware_environment.json.\n\nGPU fit probes succeeded for XGBoost and CatBoost. Installed LightGBM lacks a GPU learner; its exact error was saved and CPU fallback was used without rebuilding libraries. GPU fits were sequential, 4 CPU threads, depth/bins/VRAM conservative.\n\nOriginal training rows were partitioned by randomized, target-stratified exact labeled-record groups: {design["model_fit_rows"]:,} model-fit rows and {design["calibration_only_rows"]:,} calibration-only rows. No group crosses those roles. Base estimators and preprocessing use only model-fit rows; sigmoid/isotonic calibration uses only the reserved training rows. No refit on validation or test was performed.\n\nBMI: training median; scaled for logistic only. Categorical primary: training most frequent + one-hot, including ordinal fields. Alternatives: explicit Missing category, native categorical CatBoost, and separately labeled ordinal numeric comparison. Diabetes remains four categories; smoking remains nominal and preserves the 100-cigarette threshold. Categorical missingness under modal imputation is a statistical assumption, not a recorded No diagnosis; the explicit missing experiment is reported separately.\n\nFamilies: Dummy (most frequent/prior), logistic (unweighted/balanced), random forest (unweighted/balanced), HistGradientBoosting, XGBoost (unweighted/training ratio), LightGBM (unweighted/balanced), and CatBoost (native, one-hot, native balanced). No resampling, SMOTE, or neural network. XGBoost weighting {design["training_only_scale_pos_weight"]:.6f} uses only model-fit training frequencies.\n\nFeature configurations: full_features (16), core_features (11), no_socioeconomic (14), no_temporal_proxies (13). Earlier mobile_core experiments are retained as the historical name for the identical 11-feature core; not a fifth distinct feature configuration.\n\nTuning results: '+json.dumps(tuning,indent=2)+'\n\nLeading two boosted families were screened by validation AP; train-only RandomizedSearchCV then used a fixed 60,000-row stratified model-fit sample and grouped folds. All preprocessing is refit within each fold. Three folds bound GPU runtime; logistic regularization uses five folds. Selected settings refit the full model-fit partition. This is a bounded search, not proof of global optimum.\n\n'+table(best[['model','feature_set','device','PR_AUC','ROC_AUC','F1','Brier']])+f'\nCompleted fits: {len(successful)}; recorded failed fits: {len(failed)}. Sum of measured fit/calibration experiment runtimes plus completed tuning: {total:.1f}s, excluding interrupted work and analysis overhead. Separate preprocessing/model/calibration times are recorded where measured; historical CPU runs have only total time, not invented timing breakdowns.\n\n'+table(pd.DataFrame(bench_rows))+'\nFailure record:\n\n'+failure_text+'\n\n'+interruptions+'\n\nThe original fixed split has unequal missingness patterns: BMI missingness is approximately 12.13% train, 6.99% validation and 6.94% test. Group-based split allocation is not equivalent to unrestricted IID row splitting; this limitation is preserved and disclosed.\n'+sources
    write('training_report.md',training)
    selection=f'# Model selection report\n\nSelected experiment: {metadata["selected_experiment"]}.\n\nFamily: {metadata["model_family"]}; feature set: {metadata["feature_set"]}; {len(metadata["feature_names"])} inputs; calibration: {metadata["calibration_method"]}; threshold: {metadata["classification_threshold"]:.8f}.\n\nHyperparameters are saved exactly in model_metadata.json. Selection considered average precision first, Brier calibration, uncertainty in feature-set AP gains, removal of socioeconomic fields, threshold precision/recall/specificity, missingness checks, subgroup stability and CPU-compatible inference. It was not based on accuracy or ROC-AUC alone.\n\nThe strongest baseline families were tuned; dummy/forest and materially weaker comparisons were not heavily searched. Logistic remains a required interpretable regularization comparator. Detailed comparison rows include every successful variant and failures remain in experiment_log.csv.\n\n'+table(comparison.sort_values('PR_AUC',ascending=False).head(12)[['model','feature_set','device','calibration','PR_AUC','ROC_AUC','Brier','training_time']])+'\nFeature comparisons and matched differences:\n\n'+table(matched[['model','feature_set','PR_AUC','ROC_AUC','Brier']])+'\n\n'+json.dumps(effects,indent=2)+'\n\nExploratory group-bootstrap decisions:\n\n'+json.dumps(decisions,indent=2)+'\n\nNo arbitrary AP margin defines portability tradeoffs. Paired validation prediction intervals quantify the actual observed difference; these intervals do not certify clinical equivalence or correct repeated-selection bias. Temporal-proxy removal is not automatically preferred when it produces a clearly resolved AP reduction for this prevalent-label objective; the selected model remains unsuitable for causal/future-risk claims.\n\nThreshold maximizes validation F1 as a reproducible research operating point. Youden J, 0.50 and approximately 80%/90% recall alternatives document false-positive tradeoffs. No clinical cost ratio was supplied, so this threshold is not a clinical screening recommendation.\n\nMissingness robustness:\n\n'+table(sensitivity)+'\n\nInference of 100 validation rows took '+str(metadata['inference_100_rows_seconds'])+' seconds in the observed environment. No post-test refit: the exported artifact is exactly the independently evaluated frozen pipeline, preserving its calibration and threshold.\n\n'+table(metrics[metric_columns])+'\n\nLimitations:\n\n'+'\n'.join('- '+x for x in LIMITATIONS)
    write('model_selection_report.md',selection)
    write('calibration_report.md','# Calibration report\n\nCalibrators were fit on reserved training-only exact-record groups disjoint from base-model fit and preprocessing. FrozenEstimator prevents refitting the base model. Validation compares raw, sigmoid and isotonic; no test calibration.\n\n'+table(calibration[['feature_set','method','selected','brier','log_loss','ece','pr_auc','roc_auc']])+'\n\nChosen method: '+metadata['calibration_method']+'. The choice minimizes observed validation Brier among corresponding model versions; small differences are not asserted to be clinically meaningful. Quantile-bin curves show average predicted score against observed CHD/MI frequency. ECE uses 10 equal-width probability bins, weighted by observed bin size and absolute frequency-score gaps; this binning-dependent statistic is secondary. The model score concerns existing reported CHD/MI, never future-event probability.\n'+sources)
    stable=subgroups[(subgroups.dataset=='validation')&~subgroups.unstable]
    card_sections={
      'Model overview':f'BRFSS CHD/MI Profile Classifier {metadata["model_version"]}. Research profile classifier using {metadata["model_family"]}.',
      'Intended use':'Research/educational classification of comparable BRFSS-like adult health profiles associated with existing reported CHD/MI.',
      'Non-intended use':'Clinical diagnosis, treatment decisions, causal risk attribution, future cardiovascular-event or 10-year/30-year risk prediction. No external clinical validation has been performed.',
      'Dataset':'CDC BRFSS 2021; 434,058 supervised respondents from 438,693 raw rows; fixed 70/15/15 grouped and target-stratified splits. Unweighted respondent-level modeling; survey weights/design are not population-level estimates.',
      'Target':metadata['target_definition'],
      'Input features':', '.join(metadata['feature_names']),
      'Data preprocessing':metadata['preprocessing'],
      'Missing-value handling':metadata['imputation']+'. Missing predictors retained. All learned transformations fit in training only. Unknown cleaned categorical values are mapped to missing with a warning; invalid types, unknown names and leakage fields are rejected.',
      'Class imbalance':metadata['class_balance_method']+'. Positive class approximately 8.14%; AP dummy baseline approximately 0.0814. No oversampling/undersampling or SMOTE.',
      'Models evaluated':', '.join(sorted({r['model_family'] for r in successful})),
      'Final model':metadata['selected_experiment'],
      'Hyperparameter tuning':json.dumps(tuning,indent=2),
      'Probability calibration':metadata['calibration_method']+'; reserved training-only groups, selected by validation Brier.',
      'Classification threshold':str(metadata['classification_threshold'])+'; validation maximum F1; research operating point, not a clinical cutoff.',
      'Validation metrics':table(metrics[metrics.dataset=='validation'][metric_columns]),
      'Test metrics':table(metrics[metrics.dataset=='independent test'][metric_columns])+'Exactly one frozen model probability vector; no post-test tuning or refit. Bootstrap confidence intervals resample cached predictions only.',
      'Subgroup metrics':table(stable[['subgroup_feature','subgroup_value','rows','positive_count','precision','recall','specificity','f1','roc_auc','pr_auc']])+'Small subgroup metrics flagged unstable (n<200 or positives<30). Descriptive flags are not statistical guarantees or fairness certification; age and sex differences can reflect prevalence, self-report and selection.',
      'Explainability':'Permutation AP decreases on 2,000 stratified validation profiles, three repeats. SHAP explains contributions to the underlying uncalibrated model output, not causal disease mechanisms or the calibration transform. Built-in tree importance and regularized logistic coefficients are additional descriptive views.',
      'Known limitations':'\n'.join('- '+x for x in LIMITATIONS),
      'Ethical/portability considerations':'No formal fairness certification. Screening-dependent cholesterol and structural socioeconomic factors may encode unequal access. Income groups are U.S.-specific; external validation and a separate prospective endpoint are required before clinical use.',
    }
    write('model_card.md','# Model card\n\n'+'\n\n'.join('## '+k+'\n\n'+v for k,v in card_sections.items()))
    summary=dict(dataset_shapes={'cleaned':[434058,17],'train':[303841,17],'validation':[65109,17],'test':[65108,17]},class_counts={'train':{'negative':279115,'positive':24726},'validation':{'negative':59810,'positive':5299},'test':{'negative':59810,'positive':5298}},GPU_model=hardware['GPU_model'],CUDA_available=hardware['CUDA_available'],GPU_support=hardware['GPU_support'],benchmark=bench_rows,model_families=sorted({r['model_family'] for r in successful}),feature_configurations={k:len(v) for k,v in FEATURE_SETS.items()},selected_model=metadata,matched_feature_effects=effects,top_permutation_features=importance.head(8).to_dict('records'),missingness_sensitivity=sensitivity.fillna('').to_dict('records'),validation_subgroups=stable.fillna('').to_dict('records'),measured_total_training_seconds=total,automated_tests=json.loads((OUT/'automated_tests.json').read_text()) if (OUT/'automated_tests.json').exists() else {'passed':False,'note':'not yet run'},stage_complete=(OUT/'final_integrity_check.json').exists(),technical_backend_readiness='Artifact includes complete preprocessing/classification/calibration and input helper; ready for software integration only, no clinical validation.')
    (OUT/'final_summary.json').write_text(json.dumps(summary,indent=2,default=str))
    best_raw=comparison[(comparison.calibration=='none') & comparison.feature_set.isin(FEATURE_SETS)].sort_values('PR_AUC',ascending=False).iloc[0]
    requested=[
      ('Dataset dimensions verified',{'raw':[438693,303],**summary['dataset_shapes']}),
      ('Class distribution',{'cleaned':{'negative':398735,'positive':35323},**summary['class_counts']}),
      ('GPU detected',True),('GPU model',hardware['GPU_model']),
      ('CUDA status',{'working_GPU_probes':hardware['CUDA_available'],'driver_compatibility':hardware['driver_CUDA_compatibility_version'],'toolkit_probe':hardware['CUDA_toolkit_nvcc']}),
      ('Models using GPU',['XGBoost','CatBoost']),('GPU/CPU fallback events',hardware['GPU_support']['lightgbm']),
      ('GPU versus CPU benchmark',bench_rows),('Models trained',sorted({r['model_name'] for r in successful})),
      ('Feature sets compared',summary['feature_configurations']),
      ('Preprocessing strategies tested',['BMI training median; logistic scaling','Nominal and ordinal one-hot','Native CatBoost categorical strings','Separate ordinal numeric comparison']),
      ('Missing-value strategies tested',['Training median BMI','Training modal categorical','Explicit Missing categorical']),
      ('Imbalance strategies tested',['Unweighted','Balanced class weights','XGBoost training-only negative/positive ratio']),
      ('Models selected for tuning',tuning),
      ('Best validation model',{'raw_AP_leader':best_raw.model,'raw_AP_feature_set':best_raw.feature_set,'raw_AP':float(best_raw.PR_AUC),'exported':metadata['selected_experiment']}),
      ('Selected feature set',metadata['feature_set']),('Selected hyperparameters',metadata['hyperparameters']),
    ]
    for label,key in [('Accuracy','accuracy'),('Balanced Accuracy','balanced_accuracy'),('Precision','precision'),('Recall','recall'),('Specificity','specificity'),('F1','f1'),('ROC-AUC','roc_auc'),('PR-AUC (average precision)','pr_auc'),('Brier Score','brier')]:requested.append(('Validation '+label,metadata['validation_metrics'][key]))
    requested.extend([('Calibration method',metadata['calibration_method']),('Classification threshold',metadata['classification_threshold'])])
    for label,key in [('Accuracy','accuracy'),('Balanced Accuracy','balanced_accuracy'),('Precision','precision'),('Recall','recall'),('Specificity','specificity'),('F1','f1'),('ROC-AUC','roc_auc'),('PR-AUC (average precision)','pr_auc'),('Brier Score','brier')]:requested.append(('Test '+label,metadata['test_metrics'][key]))
    requested.extend([
      ('Final TP/TN/FP/FN',{k:metadata['test_metrics'][k] for k in ['TP','TN','FP','FN']}),
      ('Strongest model features',summary['top_permutation_features']),
      ('Full versus core difference',effects.get('core_features')),
      ('Temporal-proxy removal effect',effects.get('no_temporal_proxies')),
      ('Socioeconomic-feature removal effect',effects.get('no_socioeconomic')),
      ('Missingness sensitivity findings',summary['missingness_sensitivity']),
      ('Subgroup findings',summary['validation_subgroups']),
      ('Measured training runtime seconds',total),
      ('Final pipeline path','models/heart_disease_pipeline.joblib'),('Feature schema path','models/feature_schema.json'),
      ('Model metadata path','models/model_metadata.json'),('Model card path','reports/modeling/model_card.md'),
      ('All automated model tests pass',summary['automated_tests']['passed']),('Unresolved limitations',LIMITATIONS),
      ('Model-training stage complete',summary['stage_complete'])])
    assert len(requested)==52
    write('requested_52_item_summary.md','# Requested 52-item completion summary\n\n'+'\n\n'.join(f'{i}. **{label}:** '+(json.dumps(value,ensure_ascii=False,default=str) if not isinstance(value,str) else value) for i,(label,value) in enumerate(requested,1)))
    write('final_summary.md','# Final modeling summary\n\n'+table(metrics[metric_columns])+'\n\nSelected: '+metadata['selected_experiment']+'\n\nFeature set: '+metadata['feature_set']+'; calibration '+metadata['calibration_method']+'; threshold '+str(metadata['classification_threshold'])+'.\n\n'+table(pd.DataFrame(bench_rows))+'\n\nMatched feature effects:\n\n'+json.dumps(effects,indent=2)+'\n\nTop permutation contributions:\n\n'+table(importance.head(8))+'\n\nMissingness:\n\n'+table(sensitivity)+'\n\nSee model_card.md for subgroup details and complete limitations. Software-ready export is not clinically validated future-risk prediction. All 52 requested summary fields are represented in final_summary.json and the detailed reports.\n')
    (ROOT/'models/README.md').write_text('# Exported BRFSS CHD/MI profile classifier\n\nInstall the pinned requirements and retain the src package alongside the models directory. Use `from src.models.inference import predict_heart_disease_profile`. Supply named cleaned feature values as a dictionary or list of dictionaries, using feature_schema.json. Missing optional inputs become missing and use fitted preprocessing. Unknown feature names, target and leakage fields, numeric strings/booleans, and invalid BMI are rejected. Unseen numeric categorical codes become missing with a warning.\n\nThe helper caches the complete pipeline, calls predict_proba, and applies model_metadata.json classification_threshold. Output is a prevalent reported CHD/MI profile score, never future risk or clinical diagnosis. The artifact is the exact independently tested frozen pipeline; no post-test production refit was made.\n',encoding='utf-8')
    files=[p for folder in [ROOT/'models',OUT,ROOT/'src/models',ROOT/'tests/models'] for p in folder.rglob('*') if p.is_file() and '__pycache__' not in str(p)]
    (OUT/'generated_files.txt').write_text('\n'.join(str(p.relative_to(ROOT)) for p in sorted(files))+'\n')
    final_hashes={str(p.relative_to(ROOT)):sha(p) for p in files if p.name not in ['modeling_artifact_manifest.json','training.log']}
    (OUT/'modeling_artifact_manifest.json').write_text(json.dumps(final_hashes,indent=2))

if __name__=='__main__':generate()
